import "react-native-url-polyfill/auto";
import React from "react";
import { NavigationContainer, NavigatorScreenParams } from "@react-navigation/native";
import { createNativeStackNavigator } from "@react-navigation/native-stack";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { MaterialIcons } from "@expo/vector-icons";
import HomeScreen from "./src/screens/HomeScreen";
import CustomersListScreen from "./src/screens/CustomersListScreen";
import CustomerDetailScreen from "./src/screens/CustomerDetailScreen";
import CustomerFormScreen from "./src/screens/CustomerFormScreen";
import TransactionFormScreen from "./src/screens/TransactionFormScreen";
import DashboardScreen from "./src/screens/DashboardScreen";
import ReportsScreen from "./src/screens/ReportsScreen";
import TrashScreen from "./src/screens/TrashScreen";
import BackupScreen from "./src/screens/BackupScreen";

export type RootStackParamList = {
  MainTabs: NavigatorScreenParams<MainTabParamList> | undefined;
  CustomerDetail: { customerId: string };
  CustomerForm: { customerId?: string };
  TransactionForm: { customerId: string; initialType?: "CHARGE" | "PAYMENT" | "ADJUSTMENT" };
};

export type MainTabParamList = {
  Home: undefined;
  Customers: undefined;
  Dashboard: undefined;
  Reports: undefined;
  Trash: undefined;
  Backup: undefined;
};

const Stack = createNativeStackNavigator<RootStackParamList>();
const Tab = createBottomTabNavigator<MainTabParamList>();

function MainTabs() {
  return (
    <Tab.Navigator
      screenOptions={({ route }) => ({
        headerShown: false,
        tabBarActiveTintColor: "#007AFF",
        tabBarInactiveTintColor: "#666",
        tabBarStyle: { backgroundColor: "#fff" },
        tabBarIcon: ({ color, size }) => {
          let iconName: React.ComponentProps<typeof MaterialIcons>["name"] = "home";

          if (route.name === "Home") {
            iconName = "home";
          } else if (route.name === "Customers") {
            iconName = "people";
          } else if (route.name === "Dashboard") {
            iconName = "dashboard";
          } else if (route.name === "Reports") {
            iconName = "bar-chart";
          } else if (route.name === "Trash") {
            iconName = "delete";
          } else if (route.name === "Backup") {
            iconName = "backup";
          }

          return <MaterialIcons name={iconName} size={size} color={color} />;
        },
      })}
    >
      <Tab.Screen name="Home" component={HomeScreen} />
      <Tab.Screen name="Customers" component={CustomersListScreen} />
      <Tab.Screen name="Dashboard" component={DashboardScreen} />
      <Tab.Screen name="Reports" component={ReportsScreen} />
      <Tab.Screen name="Trash" component={TrashScreen} />
      <Tab.Screen name="Backup" component={BackupScreen} />
    </Tab.Navigator>
  );
}

export default function App() {
  return (
    <NavigationContainer>
      <Stack.Navigator>
        <Stack.Screen name="MainTabs" component={MainTabs} options={{ headerShown: false }} />
        <Stack.Screen
          name="CustomerDetail"
          component={CustomerDetailScreen}
          options={{ title: "Customer" }}
        />
        <Stack.Screen
          name="CustomerForm"
          component={CustomerFormScreen}
          options={{ title: "Customer form" }}
        />
        <Stack.Screen
          name="TransactionForm"
          component={TransactionFormScreen}
          options={{ title: "New Transaction" }}
        />
      </Stack.Navigator>
    </NavigationContainer>
  );
}
